('ad-add-spalte','06-alter-drop','Wie ergänzt man einer bestehenden Tabelle eine Spalte?',['ALTER TABLE t ADD (spalte VARCHAR2(20))','UPDATE TABLE t ADD spalte','CREATE COLUMN spalte','INSERT COLUMN spalte'],[0],'ALTER TABLE ändert die Struktur einer vorhandenen Tabelle.'),
('ad-drop-constraint','06-alter-drop','Wie entfernt man einen benannten Constraint?',['ALTER TABLE t DROP CONSTRAINT name','DROP name','DELETE CONSTRAINT name','REMOVE name FROM t'],[0],'Das setzt voraus, dass der Constraint einen Namen hat.'),
