('id-sequence-create','06-identity','Welche Anweisung legt eine Sequenz an?',['CREATE SEQUENCE s START WITH 1 INCREMENT BY 1','CREATE COUNTER s','NEW SEQUENCE s','ALTER TABLE ADD SEQUENCE'],[0],'Das Syntaxdiagramm nennt START WITH, INCREMENT BY, NOCYCLE und CACHE.'),
